begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(9);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp181@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18100000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18100000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18100000-0000-0000-0000-000000000004','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18100000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18100000-0000-0000-0000-000000000005','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18100000-0000-0000-0000-000000000006','18100000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18100000-0000-0000-0000-000000000007','18100000-0000-0000-0000-000000000002','Synthetic staff');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18100000-0000-0000-0000-000000000008','18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
grant usage on schema extensions to mcp_import;
grant execute on all functions in schema extensions to mcp_import;
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp181-browser','mcp181-browser','18100000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
select ok(has_function_privilege('mcp_import','public.prepare_mcp_shift_update(uuid,uuid,timestamptz,timestamptz,jsonb)','execute') and not has_function_privilege('authenticated','public.prepare_mcp_shift_update(uuid,uuid,timestamptz,timestamptz,jsonb)','execute'),'only MCP can prepare');
set local role mcp_import;
select throws_ok($$select public.prepare_mcp_shift_update('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008','2026-11-01 02:00+00','2026-11-01 03:00+00','[{"start_at":"2026-11-01T02:00:00Z","end_at":"2026-11-01T03:00:00Z","staffs":[{"staff_id":"18100000-0000-0000-0000-000000000007"}]}]')$$,'42501','proposal_unavailable','default disabled');
reset role;
insert into private.mcp_shift_update_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
set local role mcp_import;
select set_config('test.proposal',public.prepare_mcp_shift_update('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008','2026-11-01 02:00+00','2026-11-01 03:00+00','[{"start_at":"2026-11-01T02:00:00Z","end_at":"2026-11-01T03:00:00Z","staffs":[{"staff_id":"18100000-0000-0000-0000-000000000007"}]}]')->>'proposal_id',true);
select is(public.get_mcp_shift_update_result('18100000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'status','confirmation_required','MCP sees pending state');
reset role;
select is((select start_at from public.shifts where id='18100000-0000-0000-0000-000000000008'),'2026-11-01 00:00+00'::timestamptz,'preparation does not modify shift');
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18100000-0000-0000-0000-000000000009','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003',now());
set local role mcp_import;
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000009"}',true);
select is(public.get_mcp_shift_update_result('18100000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid),null::jsonb,'different OAuth session cannot inspect proposal');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp181-browser"}',true);
select is(public.confirm_mcp_shift_update(current_setting('test.proposal')::uuid)->>'status','updated','browser can confirm');
reset role;
set local role mcp_import;
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
select is(public.get_mcp_shift_update_result('18100000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'google_sync_status','pending_upsert','MCP sees pending Google synchronization');
reset role;
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18100000-0000-0000-0000-000000000004';
set local role mcp_import;
select throws_ok($$select public.get_mcp_shift_update_result('18100000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)$$,'42501','mcp_shift_read_unavailable','revoked connection cannot read result');
reset role;
select is((select count(*) from public.audit_events where action_type='shift.update' and resource_id='18100000-0000-0000-0000-000000000008'),1::bigint,'confirmation audited once');
select * from finish();
rollback;
